-- biocontainers/2.0: opt-in overlay (pilot).
-- Modules regenerated by bioc live in biocontainers-2.0/ and shadow the same
-- app/version in biocontainers/. Everything not yet migrated still loads from
-- the legacy tree. Loading this swaps out biocontainers/default (same name).

whatis("Name: biocontainers")
whatis("Version: 2.0")
whatis("Description: BioContainers collection, bioc-generated modules where available (pilot)")

help([[
biocontainers/2.0 - pilot of the regenerated BioContainers modules.
Modules that have been regenerated come from biocontainers-2.0; all others
come from the standard collection. Programs are also on PATH, so Perl,
Python and Nextflow can call them directly.
]])

-- Repository root from this file's own path, so the file works unchanged in
-- /opt/spack (production) and in a Modulefiles checkout under test.
local root = (myFileName():gsub("/cpu[^/]*/Core/biocontainers/[^/]+$", ""))

pushenv("BIOC_IMAGE_DIR",          "/apps/biocontainers/images")
pushenv("BIOC_SINGULARITY_MODULE", "none")
-- Lmod searches MODULEPATH front to back; the last prepend is searched first.
prepend_path("MODULEPATH", pathJoin(root, "biocontainers"))
prepend_path("MODULEPATH", pathJoin(root, "biocontainers-2.0"))

if (mode() == "load") then
    LmodMessage("biocontainers/2.0 (pilot): regenerated modules where available. User guides: https://www.rcac.purdue.edu/knowledge/biocontainers")
end
